import { notFound } from "next/navigation";
import { confirmVendorCashCollection, updateOrderStatus } from "@/app/vendor/actions";
import { SubmitButton, VendorFlash } from "@/components/vendor-forms";
import { requireVendor } from "@/lib/auth/vendor";
import { fcfa, getVendorOrder, vendorStatusLabels } from "@/services/vendor-dashboard";

const nextActions:Record<string,Array<{status:string;label:string;danger?:boolean}>>={pending:[{status:'confirmed',label:'Confirmer'},{status:'cancelled',label:'Annuler',danger:true}],confirmed:[{status:'preparing',label:'Commencer la préparation'},{status:'cancelled',label:'Annuler',danger:true}],preparing:[{status:'ready',label:'Marquer prête'},{status:'ready_for_pickup',label:'Prête pour retrait'},{status:'cancelled',label:'Annuler',danger:true}],ready:[{status:'out_for_delivery',label:'Mettre en livraison'}],ready_for_pickup:[{status:'collected',label:'Remise au client'}],out_for_delivery:[{status:'delivered',label:'Marquer livrée'}]};

export default async function Page({params,searchParams}:{params:Promise<{id:string}>;searchParams:Promise<{updated?:string;error?:string}>}) {
  const [{id},query,context]=await Promise.all([params,searchParams,requireVendor()]);
  const row=await getVendorOrder(context.restaurant!.id,id);if(!row)notFound();
  const order=row.order as unknown as Record<string,unknown>,items=(row.items??[]) as Array<Record<string,unknown>>,fulfillment=String(order.fulfillment),paymentMethod=String(order.payment_method),paymentStatus=String(row.payment_status??order.payment_status);
  const actions=(nextActions[row.status]??[]).filter(action=>!(action.status==='ready'&&fulfillment==='pickup')&&!(action.status==='ready_for_pickup'&&fulfillment==='delivery'));
  return <>
    <VendorFlash message={query.error?'La commande n’a pas pu être mise à jour.':query.updated==='cash-collected'?'Paiement en espèces encaissé.':query.updated?'Commande mise à jour.':undefined}/>
    <div className="vendor-page-head"><div><p className="section-kicker">Commande</p><h1>{String(order.reference)}</h1><p>{new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(String(order.created_at)))}</p></div><span className={`vendor-badge ${row.status}`}>{vendorStatusLabels[row.status]}</span></div>
    <div className="vendor-order-detail"><section className="vendor-card"><h2>Produits</h2>{items.map(item=><article className="vendor-order-item" key={String(item.id)}><span><strong>{Number(item.quantity)} × {String(item.product_name)}</strong><small>{Array.isArray(item.options)&&item.options.length?(item.options as Array<{name?:string}>).map(option=>option.name).filter(Boolean).join(', '):'Sans option'}</small></span><b>{fcfa(Number(item.line_total))}</b></article>)}<div className="finance-breakdown"><span>Montant <strong>{fcfa(row.gross_amount??row.subtotal)}</strong></span><span>Taux <strong>{(row.commission_rate_bps??0)/100} %</strong></span><span>{row.status==='cancelled'?'Commission historique':'Commission Come & Eat'} <strong>{fcfa(row.platform_commission??0)}</strong></span><span>Net <strong>{fcfa(row.seller_net_amount??row.subtotal)}</strong></span></div></section>
      <aside><section className="vendor-card customer-summary"><h2>Client et réception</h2><dl><div><dt>Nom</dt><dd>{String(order.customer_name)}</dd></div><div><dt>Téléphone</dt><dd><a href={`tel:${String(order.customer_phone)}`}>{String(order.customer_phone)}</a></dd></div><div><dt>Livraison / retrait</dt><dd>{fulfillment==='pickup'?'Retrait':'Livraison'}</dd></div>{fulfillment==='delivery'?<><div><dt>Zone</dt><dd>{String(order.commune??'—')}</dd></div><div><dt>Adresse précise</dt><dd>{String(order.address??'Non précisée')}</dd></div></>:null}<div><dt>Moyen de paiement</dt><dd>{paymentMethod==='cash'?'Espèces':'Wave'}</dd></div><div><dt>Statut du paiement</dt><dd>{paymentStatus==='paid'?(paymentMethod==='cash'?'Encaissé':'Payé'):(paymentMethod==='cash'?'À encaisser':'À vérifier')}</dd></div><div><dt>Instructions</dt><dd>{String(order.customer_note??'Aucune')}</dd></div></dl>
      {paymentMethod==='cash'&&paymentStatus!=='paid'?<form action={confirmVendorCashCollection}><input type="hidden" name="order_id" value={row.id}/><SubmitButton className="btn btn-orange" pendingLabel="Confirmation…" confirmMessage="Confirmer que le paiement en espèces a bien été encaissé ?">Marquer comme encaissé</SubmitButton></form>:null}</section>
      {actions.length?<section className="vendor-card order-actions"><h2>Mettre à jour</h2>{actions.map(action=><form action={updateOrderStatus} key={action.status}><input type="hidden" name="order_id" value={row.id}/><input type="hidden" name="status" value={action.status}/><SubmitButton className={action.danger?'btn btn-danger':'btn btn-dark'} pendingLabel="Mise à jour…" confirmMessage={action.danger?'Annuler cette commande ?':undefined}>{action.label}</SubmitButton></form>)}</section>:null}</aside>
    </div>
  </>;
}
